<template><div class="knowledge-graph"><canvas ref="c" style="width:100%;height:400px" /></div></template><script>export default { name: 'KnowledgeGraph', mounted() { const c=this.$refs.c; if(c){c.width=c.offsetWidth;c.height=c.offsetHeight;const ctx=c.getContext('2d');ctx.fillStyle='#1e3a5f';ctx.font='18px sans-serif';ctx.textAlign='center';ctx.fillText('知识图谱',c.width/2,c.height/2)} } }</script>